import numpy as np
def f(inp):
    A=np.array(inp); B=A.copy()
    rs,cs=np.where(A==3)
    r0,r1,c0,c1=rs.min(),rs.max(),cs.min(),cs.max()
    ch=int((r1+r0)/2); cw=int((c1+c0)/2)
    for i in range(r1-r0):
        for j in range(c1-c0):
            v=A[r0+i,c0+j]
